const body = $json.raw_email || '';

const match = body.match(
  /Rs\.?\s*([\d,.]+).*?(debited|credited).*?ending\s+(\d{4}).*?towards\s+(.+?)\s+on\s+(\d{1,2}\s+[A-Za-z]{3},?\s+\d{4})/i
);

if (!match) {
  return [{
    json: {
      parsed: false,
      reason: 'no-regex-match',
      body
    }
  }];
}

return [{
  json: {
    parsed: true,
    bank: 'HDFC',

    amount: Number(
      match[1].replace(/,/g, '')
    ),

    transaction_type: match[2].toUpperCase(),

    card_last4: match[3],

    merchant: match[4].trim(),

    transaction_date: match[5],

    raw_email: body,

    processed_at: new Date().toISOString()
  }
}];

// Build final transaction row.
// Input can come from either:
// 1. Merchant Memory (known merchant)
// 2. Claude Categorizer (new merchant)

const data = $input.item.json;

return [{
  json: {

    user_id: '2f324f4d-1dc3-4ec5-8c23-93da480842c7',

    amount: Number(data.amount),

    currency: data.currency || 'INR',

    transaction_date: data.transaction_date,

    merchant: data.display_name || data.merchant,

    category: data.category || null,

    card_last4: data.card_last4,

    bank_name: data.bank,

    transaction_type: data.transaction_type,

    raw_email: data.raw_email || null,

    confidence: data.confidence || null,

    is_manually_entered: false,

    status: 'auto',

    processed_at: new Date().toISOString()

  }
}];

const original = $('Parse HDFC (regex)').item.json;

const items = $input.all();

// If Dedupe returned an empty placeholder item
const isEmpty =
  items.length === 1 &&
  Object.keys(items[0].json || {}).length === 0;

const duplicateCount =
  isEmpty
    ? 0
    : items.length;

return [{
  json: {
    ...original,
    duplicate_count: duplicateCount
  }
}];

const merchant = ($('Parse HDFC (regex)').item.json.merchant || '').toUpperCase();

const rules = {
  'MYNTRA': 'Shopping',
  'AMAZON': 'Shopping',
  'FLIPKART': 'Shopping',
  'SWIGGY': 'Food',
  'ZOMATO': 'Food',
  'UBER': 'Travel',
  'OLA': 'Travel',
  'AIRTEL': 'Utilities',
  'JIO': 'Utilities',
  'HPCL': 'Fuel',
  'IOCL': 'Fuel',
  'BPCL': 'Fuel'
};

let category = null;

for (const key of Object.keys(rules)) {
  if (merchant.includes(key)) {
    category = rules[key];
    break;
  }
}

return [{
  json: {
    merchant,
    category
  }
}];

const j = $json;

// -----------------------------
// Helper: Convert Gmail address objects to string
// -----------------------------
function getAddress(value) {
  if (!value) return '';

  if (typeof value === 'string') return value;

  if (Array.isArray(value)) {
    return value
      .map(v => v?.address || v?.text || '')
      .filter(Boolean)
      .join(', ');
  }

  return value.address || value.text || '';
}

// -----------------------------
// Canonical email body
// -----------------------------
const raw_email =
  j.text ||
  j.html ||
  j.textAsHtml ||
  '';

if (!raw_email) {
  throw new Error('Email body is empty');
}

// -----------------------------
// Normalize
// -----------------------------
return {
  json: {

    // ---------- Identity ----------
    user_id: j.user_id,

    source_message_id:
      j.message_id ||
      j.id,

    thread_id:
      j.thread_id ||
      j.threadId ||
      null,

    // ---------- Email ----------
    subject:
      j.subject || '',

    sender:
      getAddress(j.from),

    recipient:
      getAddress(j.to),

    received_at:
      j.received_at ||
      j.date ||
      null,

    raw_email,

    source: 'gmail',

    // ---------- Preserve everything ----------
    ...j
  }
};

const j = $json;

const sender = String(j.sender || '').toLowerCase();
const subject = String(j.subject || '').toLowerCase();
const body = String(j.raw_email || '').toLowerCase();

const combined = `${sender} ${subject} ${body}`;

let bank = 'UNKNOWN';

/*
 * ============================================================
 * BANK DETECTION
 * ============================================================
 *
 * Priority:
 * 1. Sender/domain signals
 * 2. Explicit bank names in subject/body
 *
 * Canonical bank codes used downstream:
 * HDFC
 * ICICI
 * AXIS
 * SBI
 * AU_BANK
 * AMEX
 * KOTAK
 * YES_BANK
 * IDFC_FIRST
 * INDUSIND
 * STANDARD_CHARTERED
 * CITI
 * HSBC
 */

// ------------------------------------------------------------
// 1. Strong sender/domain signals
// ------------------------------------------------------------

if (
  sender.includes('hdfcbank') ||
  sender.includes('hdfc.bank') ||
  sender.includes('hdfcbank.com') ||
  sender.includes('hdfcbank.net')
) {
  bank = 'HDFC';

} else if (
  sender.includes('icicibank') ||
  sender.includes('icici.bank') ||
  sender.includes('icici.com')
) {
  bank = 'ICICI';

} else if (
  sender.includes('axisbank') ||
  sender.includes('axis.bank') ||
  sender.includes('axis.com')
) {
  bank = 'AXIS';

} else if (
  sender.includes('sbi.co.in') ||
  sender.includes('sbicard') ||
  sender.includes('sbi') ||
  sender.includes('statebank')
) {
  bank = 'SBI';

} else if (
  sender.includes('aubank') ||
  sender.includes('au.bank') ||
  sender.includes('au.bank.in')
) {
  bank = 'AU_BANK';

} else if (
  sender.includes('americanexpress') ||
  sender.includes('aexp')
) {
  bank = 'AMEX';

} else if (
  sender.includes('kotak')
) {
  bank = 'KOTAK';

} else if (
  sender.includes('yesbank') ||
  sender.includes('yes.bank')
) {
  bank = 'YES_BANK';

} else if (
  sender.includes('idfc')
) {
  bank = 'IDFC_FIRST';

} else if (
  sender.includes('indusind')
) {
  bank = 'INDUSIND';

} else if (
  sender.includes('sc.com') ||
  sender.includes('standardchartered')
) {
  bank = 'STANDARD_CHARTERED';

} else if (
  sender.includes('citibank') ||
  sender.includes('citi.com')
) {
  bank = 'CITI';

} else if (
  sender.includes('hsbc')
) {
  bank = 'HSBC';


// ------------------------------------------------------------
// 2. Explicit bank names in subject/body
// ------------------------------------------------------------

} else if (
  /\bhdfc\s*bank\b/i.test(combined) ||
  /\bhdfc\s*(?:credit\s*)?card\b/i.test(combined)
) {
  bank = 'HDFC';

} else if (
  /\bicici\s*bank\b/i.test(combined) ||
  /\bicici\s*(?:credit\s*)?card\b/i.test(combined)
) {
  bank = 'ICICI';

} else if (
  /\baxis\s*bank\b/i.test(combined) ||
  /\baxis\s*(?:credit\s*)?card\b/i.test(combined)
) {
  bank = 'AXIS';

} else if (
  /\bstate\s*bank\s*of\s*india\b/i.test(combined) ||
  /\bsbi\s*card\b/i.test(combined) ||
  /\bsbi\s*(?:credit\s*)?card\b/i.test(combined)
) {
  bank = 'SBI';

} else if (
  /\bau\s*bank\b/i.test(combined) ||
  /\bau\s*small\s*finance\s*bank\b/i.test(combined) ||
  /\bau\s*bank\s*(?:credit\s*)?card\b/i.test(combined)
) {
  bank = 'AU_BANK';

} else if (
  /\bamerican\s*express\b/i.test(combined) ||
  /\bamex\b/i.test(combined)
) {
  bank = 'AMEX';

} else if (
  /\bkotak\s*(?:mahindra\s*)?bank\b/i.test(combined) ||
  /\bkotak\s*(?:credit\s*)?card\b/i.test(combined)
) {
  bank = 'KOTAK';

} else if (
  /\byes\s*bank\b/i.test(combined) ||
  /\byesbank\b/i.test(combined) ||
  /\byes\s*bank\s*(?:credit\s*)?card\b/i.test(combined)
) {
  bank = 'YES_BANK';

} else if (
  /\bidfc\s*(?:first\s*)?bank\b/i.test(combined) ||
  /\bidfc\s*first\b/i.test(combined)
) {
  bank = 'IDFC_FIRST';

} else if (
  /\bindusind\s*bank\b/i.test(combined) ||
  /\bindusind\b/i.test(combined)
) {
  bank = 'INDUSIND';

} else if (
  /\bstandard\s*chartered\b/i.test(combined)
) {
  bank = 'STANDARD_CHARTERED';

} else if (
  /\bcitibank\b/i.test(combined) ||
  /\bciti\s*bank\b/i.test(combined)
) {
  bank = 'CITI';

} else if (
  /\bhsbc\b/i.test(combined)
) {
  bank = 'HSBC';
}


// ------------------------------------------------------------
// 3. Detect source type
// ------------------------------------------------------------

let source_type = 'UNKNOWN';

const detectionText = `${j.subject || ''} ${j.raw_email || ''}`;

if (
  /credit\s*card/i.test(detectionText) ||
  /card\s*(?:ending|xx|xxxx|\*{2,})/i.test(detectionText) ||
  /credit\s*card\s*transaction/i.test(detectionText)
) {
  source_type = 'CREDIT_CARD_ALERT';

} else if (
  /\baccount\b/i.test(detectionText) ||
  /\ba\/c\b/i.test(detectionText) ||
  /\bacct\b/i.test(detectionText) ||
  /\bsavings\b/i.test(detectionText) ||
  /\bcurrent\s+account\b/i.test(detectionText)
) {
  source_type = 'BANK_ACCOUNT_ALERT';
}


// ------------------------------------------------------------
// 4. Detect transaction hint
// ------------------------------------------------------------

let transaction_hint = null;

if (
  /\b(debited|debit|spent|purchase|paid|withdrawn|withdrawal)\b/i.test(
    detectionText
  )
) {
  transaction_hint = 'DEBIT';

} else if (
  /\b(credited|credit|received|refund|reversal)\b/i.test(
    detectionText
  )
) {
  transaction_hint = 'CREDIT';
}


// ------------------------------------------------------------
// 5. Return original data + detected metadata
// ------------------------------------------------------------

return {
  json: {
    ...j,

    bank,

    source_type,

    transaction_hint
  }
};

const j = $json;

// ============================================================
// 1. NORMALIZE INPUT
// ============================================================

function toText(value) {
  if (value == null) return '';

  if (typeof value === 'string') {
    return value;
  }

  if (Array.isArray(value)) {
    return value
      .map(v => toText(v))
      .filter(Boolean)
      .join('\n');
  }

  if (typeof value === 'object') {
    // Handle common shapes without producing [object Object]
    if (typeof value.text === 'string') return value.text;
    if (typeof value.value === 'string') return value.value;

    return Object.values(value)
      .map(v => toText(v))
      .filter(Boolean)
      .join('\n');
  }

  return String(value);
}

const text = toText(j.raw_email)
  .replace(/\\r/g, '\r')
  .replace(/\\n/g, '\n')
  .replace(/\u00A0/g, ' ')
  .replace(/[ \t]+/g, ' ')
  .trim();

const subject = toText(j.subject).trim();

const combinedText = `${subject}\n${text}`;


// ============================================================
// 2. GENERIC HELPERS
// ============================================================

function firstMatch(input, patterns) {
  for (const pattern of patterns) {
    const match = input.match(pattern);

    if (match) {
      return match;
    }
  }

  return null;
}


function cleanAmount(value) {
  if (value == null) return null;

  const cleaned = String(value)
    .replace(/,/g, '')
    .replace(/[^\d.]/g, '');

  if (!cleaned) return null;

  const num = Number(cleaned);

  return Number.isFinite(num) && num > 0
    ? num
    : null;
}


function cleanLast4(value) {
  if (value == null) return null;

  const digits = String(value).replace(/\D/g, '');

  if (digits.length < 4) return null;

  return digits.slice(-4);
}


function cleanMerchant(value) {
  if (!value) return null;

  let merchant = String(value)
    .replace(/[\r\n]+/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();

  // Remove common trailing transaction metadata if accidentally captured
  merchant = merchant
    .replace(
      /\s+(?:on|dated)\s+\d{1,2}[-\/]\d{1,2}[-\/]\d{2,4}.*$/i,
      ''
    )
    .replace(
      /\s+(?:on|dated)\s+\d{1,2}\s+[A-Za-z]{3,9}\s+\d{2,4}.*$/i,
      ''
    )
    .replace(
      /\s+(?:ref(?:erence)?|txn|transaction)\s*(?:no|id|#)?[\s:.-].*$/i,
      ''
    )
    .replace(/[.,;:\-\s]+$/g, '')
    .trim();

  if (
    merchant.length < 2 ||
    merchant.length > 150
  ) {
    return null;
  }

  // Reject obvious non-merchants
  const invalid = [
    /^your$/i,
    /^card$/i,
    /^account$/i,
    /^bank$/i,
    /^available balance$/i,
    /^available credit limit$/i,
    /^credit card$/i,
    /^debit card$/i
  ];

  if (invalid.some(pattern => pattern.test(merchant))) {
    return null;
  }

  return merchant;
}


// ============================================================
// 3. AMOUNT EXTRACTION
// ============================================================

function extractAmount(input) {

  // Strong patterns:
  // INR 333.79 were spent
  // Rs. 8850 has been debited
  // ₹7,850 debited
  // amount of INR 3,000
  // transaction of Rs 638

  const strongPatterns = [

    /(?:INR|Rs\.?|₹)\s*([\d,]+(?:\.\d{1,2})?)\s+(?:was|were|has\s+been|have\s+been)?\s*(?:debited|credited|spent|charged|paid|withdrawn|used|transferred|received|purchased)/i,

    /(?:debited|credited|spent|charged|paid|withdrawn|used|transferred|received|purchase(?:d)?)\s+(?:for|by|with|of)?\s*(?:INR|Rs\.?|₹)?\s*([\d,]+(?:\.\d{1,2})?)/i,

    /(?:amount|transaction|purchase|payment)\s+(?:of|for)?\s*(?:INR|Rs\.?|₹)\s*([\d,]+(?:\.\d{1,2})?)/i

  ];

  let match = firstMatch(input, strongPatterns);

  if (match?.[1]) {
    return cleanAmount(match[1]);
  }


  // Currency-first fallback.
  // Must remain conservative because emails may contain:
  // available balance, credit limit, helpline numbers, OTP etc.

  const currencyPattern =
    /(?:INR|Rs\.?|₹)\s*([\d,]+(?:\.\d{1,2})?)/gi;

  const candidates = [];

  let m;

  while ((m = currencyPattern.exec(input)) !== null) {

    const amount = cleanAmount(m[1]);

    if (!amount) continue;

    const start = Math.max(0, m.index - 80);

    const end = Math.min(
      input.length,
      m.index + m[0].length + 100
    );

    const context = input.slice(start, end);

    const transactionWords =
      /\b(debit(?:ed)?|credit(?:ed)?|spent|charged|paid|purchase(?:d)?|withdrawn|used|transaction)\b/i;

    const balanceWords =
      /\b(available\s+(?:balance|credit|limit)|credit\s+limit|outstanding|minimum\s+due|total\s+due)\b/i;

    if (
      transactionWords.test(context) &&
      !balanceWords.test(context)
    ) {
      candidates.push(amount);
    }
  }

  return candidates.length
    ? candidates[0]
    : null;
}


// ============================================================
// 4. CARD LAST 4 EXTRACTION
// ============================================================

function extractCardLast4(input) {

  const patterns = [

    /(?:credit|debit)\s*card[\s\S]{0,40}?(?:ending\s*(?:in)?|ending|xx|xxxx|x{2,}|\*{2,})\s*(\d{4})/i,

    /\bcard[\s\S]{0,25}?(?:ending\s*(?:in)?|xx|xxxx|x{2,}|\*{2,})\s*(\d{4})/i,

    /\b(?:xx|xxxx|x{2,}|\*{2,})\s*(\d{4})\b/i,

    /\bcard\s+(?:no\.?|number)?\s*[:\-]?\s*(?:x+|\*+)?\s*(\d{4})\b/i

  ];

  const match = firstMatch(input, patterns);

  return match?.[1]
    ? cleanLast4(match[1])
    : null;
}


// ============================================================
// 5. ACCOUNT LAST 4 EXTRACTION
// ============================================================

function extractAccountLast4(input) {

  const patterns = [

    /(?:a\/c|acct|account)[\s\S]{0,25}?(?:ending\s*(?:in)?|xx|xxxx|x{2,}|\*{2,})\s*(\d{4})/i,

    /(?:a\/c|acct|account)\s*(?:no\.?|number)?\s*[:\-]?\s*(?:x+|\*+)?\s*(\d{4})/i

  ];

  const match = firstMatch(input, patterns);

  return match?.[1]
    ? cleanLast4(match[1])
    : null;
}


// ============================================================
// 6. TRANSACTION TYPE
// ============================================================

function extractTransactionType(input, hint) {

  const normalizedHint =
    String(hint || '').toUpperCase();

  if (
    normalizedHint === 'DEBIT' ||
    normalizedHint === 'CREDIT'
  ) {
    return normalizedHint;
  }

  if (
    /\b(debited|spent|purchase(?:d)?|charged|withdrawn|paid|payment\s+made|used\s+(?:your|the)?\s*(?:credit|debit)?\s*card)\b/i
      .test(input)
  ) {
    return 'DEBIT';
  }

  if (
    /\b(credited|received|refund(?:ed)?|cashback|reversal|reversed)\b/i
      .test(input)
  ) {
    return 'CREDIT';
  }

  return null;
}


// ============================================================
// 7. CURRENCY
// ============================================================

function extractCurrency(input) {

  if (
    /\bINR\b/i.test(input) ||
    /Rs\.?\s*[\d,]/i.test(input) ||
    /₹\s*[\d,]/.test(input)
  ) {
    return 'INR';
  }

  if (
    /\bUSD\b/i.test(input) ||
    /\$\s*[\d,]/.test(input)
  ) {
    return 'USD';
  }

  if (
    /\bEUR\b/i.test(input) ||
    /€\s*[\d,]/.test(input)
  ) {
    return 'EUR';
  }

  if (
    /\bGBP\b/i.test(input) ||
    /£\s*[\d,]/.test(input)
  ) {
    return 'GBP';
  }

  if (/\bAUD\b/i.test(input)) {
    return 'AUD';
  }

  if (/\bSGD\b/i.test(input)) {
    return 'SGD';
  }

  if (/\bAED\b/i.test(input)) {
    return 'AED';
  }

  return null;
}


// ============================================================
// 8. DATE PARSING
// ============================================================

function normalizeYear(year) {

  let y = Number(year);

  if (y < 100) {
    y += y >= 70
      ? 1900
      : 2000;
  }

  return y;
}


function validDate(year, month, day) {

  const date = new Date(
    Date.UTC(year, month - 1, day)
  );

  if (
    date.getUTCFullYear() !== year ||
    date.getUTCMonth() !== month - 1 ||
    date.getUTCDate() !== day
  ) {
    return null;
  }

  return `${year}-${String(month).padStart(2, '0')}-${String(day).padStart(2, '0')}`;
}


function monthNumber(name) {

  const months = {
    jan: 1,
    january: 1,

    feb: 2,
    february: 2,

    mar: 3,
    march: 3,

    apr: 4,
    april: 4,

    may: 5,

    jun: 6,
    june: 6,

    jul: 7,
    july: 7,

    aug: 8,
    august: 8,

    sep: 9,
    sept: 9,
    september: 9,

    oct: 10,
    october: 10,

    nov: 11,
    november: 11,

    dec: 12,
    december: 12
  };

  return months[String(name).toLowerCase()] || null;
}


function extractTransactionDate(input, receivedAt) {

  // DD-MM-YYYY / DD/MM/YYYY
  let match = input.match(
    /\b(\d{1,2})[-\/](\d{1,2})[-\/](\d{2,4})\b/
  );

  if (match) {

    const day = Number(match[1]);
    const month = Number(match[2]);
    const year = normalizeYear(match[3]);

    const result = validDate(year, month, day);

    if (result) return result;
  }


  // DD Mon YYYY
  match = input.match(
    /\b(\d{1,2})[\s\-]+(Jan(?:uary)?|Feb(?:ruary)?|Mar(?:ch)?|Apr(?:il)?|May|Jun(?:e)?|Jul(?:y)?|Aug(?:ust)?|Sep(?:t|tember)?|Oct(?:ober)?|Nov(?:ember)?|Dec(?:ember)?)[\s,\-]+(\d{2,4})\b/i
  );

  if (match) {

    const day = Number(match[1]);
    const month = monthNumber(match[2]);
    const year = normalizeYear(match[3]);

    const result = validDate(year, month, day);

    if (result) return result;
  }


  // Mon DD YYYY
  match = input.match(
    /\b(Jan(?:uary)?|Feb(?:ruary)?|Mar(?:ch)?|Apr(?:il)?|May|Jun(?:e)?|Jul(?:y)?|Aug(?:ust)?|Sep(?:t|tember)?|Oct(?:ober)?|Nov(?:ember)?|Dec(?:ember)?)\s+(\d{1,2}),?\s+(\d{2,4})\b/i
  );

  if (match) {

    const month = monthNumber(match[1]);
    const day = Number(match[2]);
    const year = normalizeYear(match[3]);

    const result = validDate(year, month, day);

    if (result) return result;
  }


  // Some bank alerts only contain day/month without year.
  // Use received year only when needed.

  match = input.match(
    /\b(\d{1,2})[-\/](\d{1,2})\b/
  );

  if (match && receivedAt) {

    const received = new Date(receivedAt);

    if (!Number.isNaN(received.getTime())) {

      const day = Number(match[1]);
      const month = Number(match[2]);

      let year = received.getUTCFullYear();

      let candidate = new Date(
        Date.UTC(year, month - 1, day)
      );

      // Avoid accidentally assigning a future date
      // around year boundaries.

      const futureTolerance =
        7 * 24 * 60 * 60 * 1000;

      if (
        candidate.getTime() >
        received.getTime() + futureTolerance
      ) {
        year--;
      }

      const result = validDate(
        year,
        month,
        day
      );

      if (result) return result;
    }
  }

  return null;
}


// ============================================================
// 9. MERCHANT EXTRACTION
// ============================================================

function extractMerchant(input) {

  /*
    Important principle:

    We do NOT identify merchants by bank.

    We identify the grammatical relationship around
    transaction phrases:

    "at MERCHANT on DATE"
    "towards MERCHANT"
    "to MERCHANT"
    "spent at MERCHANT"
    "transaction at MERCHANT"
    "purchase at MERCHANT"
  */

  const patterns = [

    // Example:
    // Card xx2723 at INNOVATIVE RETAIL CONC on 19-07-2026

    /(?:card|a\/c|acct|account)[\s\S]{0,60}?(?:xx|xxxx|x{2,}|\*{2,}|ending\s+(?:in\s+)?)?\d{4}[\s\S]{0,30}?\b(?:at|towards)\s+(.+?)(?=\s+(?:on|dated)\s+\d{1,2}[-\/]\d{1,2}[-\/]\d{2,4}\b|[.\n]|$)/i,


    // Example:
    // debited ... towards DECATHLON SPORTS INDIA PRIVATE LIMITED on 17...

    /\b(?:debited|spent|charged|paid|purchase(?:d)?|used|transaction)\b[\s\S]{0,180}?\b(?:at|towards)\s+(.+?)(?=\s+(?:on|dated)\s+(?:\d{1,2}[-\/]\d{1,2}[-\/]\d{2,4}|\d{1,2}\s+[A-Za-z]{3,9}\s+\d{2,4})\b|[.\n]|$)/i,


    // Generic "towards merchant"

    /\btowards\s+(.+?)(?=\s+(?:on|dated)\s+(?:\d{1,2}[-\/]\d{1,2}[-\/]\d{2,4}|\d{1,2}\s+[A-Za-z]{3,9}\s+\d{2,4})\b|[.\n]|$)/i,


    // Generic "at merchant on date"

    /\bat\s+(.+?)(?=\s+(?:on|dated)\s+(?:\d{1,2}[-\/]\d{1,2}[-\/]\d{2,4}|\d{1,2}\s+[A-Za-z]{3,9}\s+\d{2,4})\b|[.\n]|$)/i,


    // Merchant followed by reference/transaction ID

    /\b(?:at|towards)\s+(.+?)(?=\s+(?:ref(?:erence)?|txn|transaction)\s*(?:no|id|#)?[\s:.-])/i

  ];

  for (const pattern of patterns) {

    const match = input.match(pattern);

    if (match?.[1]) {

      const merchant =
        cleanMerchant(match[1]);

      if (merchant) {
        return merchant;
      }
    }
  }

  return null;
}


// ============================================================
// 10. EXTRACT ALL TRANSACTION FIELDS
// ============================================================

const amount =
  extractAmount(combinedText);

const card_last4 =
  extractCardLast4(combinedText);

const account_last4 =
  extractAccountLast4(combinedText);

const transaction_type =
  extractTransactionType(
    combinedText,
    j.transaction_hint
  );

const currency =
  extractCurrency(combinedText);

const transaction_date =
  extractTransactionDate(
    combinedText,
    j.received_at
  );

const merchant_raw =
  extractMerchant(combinedText);


// ============================================================
// 11. DETERMINE WHETHER FAST PARSE IS SAFE
// ============================================================

/*
  We intentionally do NOT require merchant for every transaction.

  Example:
  ATM withdrawals, bank charges, transfers, refunds,
  account transactions may legitimately not have a merchant.

  But for card purchase/spend alerts, missing merchant means
  the parser should fall back to Gemini.
*/

const looksLikeCardPurchase =
  /\b(?:spent|purchase(?:d)?|merchant|charged|card\s+(?:was\s+)?used)\b/i
    .test(combinedText) ||
  (
    j.source_type === 'CREDIT_CARD_ALERT' &&
    transaction_type === 'DEBIT'
  );


const coreFieldsPresent =
  amount !== null &&
  transaction_date !== null &&
  transaction_type !== null;


const instrumentPresent =
  card_last4 !== null ||
  account_last4 !== null;


const merchantRequirementMet =
  !looksLikeCardPurchase ||
  merchant_raw !== null;


const parsed =
  Boolean(
    coreFieldsPresent &&
    instrumentPresent &&
    merchantRequirementMet
  );


// ============================================================
// 12. PARSE QUALITY / DEBUG INFORMATION
// ============================================================

const missing_fields = [];

if (amount === null)
  missing_fields.push('amount');

if (transaction_date === null)
  missing_fields.push('transaction_date');

if (transaction_type === null)
  missing_fields.push('transaction_type');

if (
  card_last4 === null &&
  account_last4 === null
)
  missing_fields.push('card_or_account_last4');

if (
  looksLikeCardPurchase &&
  merchant_raw === null
)
  missing_fields.push('merchant_raw');


// ============================================================
// 13. OUTPUT
// ============================================================

return {
  json: {

    // Preserve upstream context
    ...j,

    // Ensure canonical email remains a string
    raw_email: text,

    // Extraction result
    parsed,

    amount,

    merchant_raw,

    card_last4,

    account_last4,

    transaction_date,

    transaction_type,

    currency,

    parser_used:
      parsed
        ? 'fast_parser'
        : 'gemini_required',

    missing_fields
  }
};

// ============================================================
// NORMALIZE GEMINI OUTPUT
// Mode: Run Once for Each Item
// ============================================================

// Gemini HTTP response
const response = $json;

// Recover the original transaction context from the node
// immediately before Gemini Extraction.
// Change "Build Gemini Request" only if your node has another name.
const original = $('Build Gemini Request').item.json;

// ------------------------------------------------------------
// 1. Read Gemini response text
// ------------------------------------------------------------

let responseText =
  response?.candidates?.[0]?.content?.parts?.[0]?.text ?? '';

if (typeof responseText !== 'string') {
  responseText = String(responseText ?? '');
}

// Remove markdown fences if Gemini ever returns them
responseText = responseText
  .replace(/^```json\s*/i, '')
  .replace(/^```\s*/i, '')
  .replace(/\s*```$/i, '')
  .trim();

// ------------------------------------------------------------
// 2. Parse Gemini JSON
// ------------------------------------------------------------

let extracted = {};

try {
  extracted = JSON.parse(responseText);
} catch (error) {
  extracted = {};
}

// ------------------------------------------------------------
// 3. Helper functions
// ------------------------------------------------------------

function normalizeAmount(value) {
  if (value === null || value === undefined || value === '') {
    return null;
  }

  const cleaned = String(value)
    .replace(/,/g, '')
    .replace(/[^\d.-]/g, '');

  const num = Number(cleaned);

  return Number.isFinite(num) && num > 0
    ? num
    : null;
}

function normalizeLast4(value) {
  if (value === null || value === undefined) {
    return null;
  }

  const digits = String(value).replace(/\D/g, '');

  if (digits.length < 4) {
    return null;
  }

  return digits.slice(-4);
}

function normalizeCurrency(value) {
  if (!value) return null;

  const currency = String(value)
    .trim()
    .toUpperCase();

  return currency || null;
}

function normalizeTransactionType(value) {
  if (!value) return null;

  const type = String(value)
    .trim()
    .toUpperCase();

  if (type === 'DEBIT' || type === 'CREDIT') {
    return type;
  }

  return null;
}

function normalizeDate(value) {
  if (!value) return null;

  const raw = String(value).trim();

  // Already YYYY-MM-DD
  if (/^\d{4}-\d{2}-\d{2}$/.test(raw)) {
    return raw;
  }

  const parsed = new Date(raw);

  if (!Number.isNaN(parsed.getTime())) {
    return parsed.toISOString().slice(0, 10);
  }

  return null;
}

// ------------------------------------------------------------
// 4. Build ONE final normalized transaction
// ------------------------------------------------------------

const result = {

  // Customer / tenant identity
  user_id:
    original.user_id ??
    null,

  // Gmail identity
  source_message_id:
    original.source_message_id ??
    original.message_id ??
    original.id ??
    null,

  thread_id:
    original.thread_id ??
    original.threadId ??
    null,

  // Email metadata
  subject:
    original.subject ??
    '',

  sender:
    original.sender ??
    '',

  recipient:
    original.recipient ??
    '',

  received_at:
    original.received_at ??
    null,

  raw_email:
    original.raw_email ??
    '',

  source:
    original.source ??
    'gmail',

  // Detection context
  bank:
    original.bank ??
    null,

  source_type:
    original.source_type ??
    null,

  transaction_hint:
    original.transaction_hint ??
    null,

  // Gemini extraction
  parsed: true,

  amount:
    normalizeAmount(extracted.amount),

  merchant_raw:
    extracted.merchant_raw
      ? String(extracted.merchant_raw).trim()
      : null,

  card_last4:
    normalizeLast4(extracted.card_last4),

  account_last4:
    normalizeLast4(extracted.account_last4),

  transaction_date:
    normalizeDate(extracted.transaction_date),

  transaction_type:
    normalizeTransactionType(
      extracted.transaction_type
    ),

  currency:
    normalizeCurrency(extracted.currency),

  confidence:
    Number.isFinite(Number(extracted.confidence))
      ? Number(extracted.confidence)
      : null,

  parser_used:
    'gemini'
};

// ------------------------------------------------------------
// 5. Validate FINAL normalized object
// ------------------------------------------------------------

const missing_fields = [];

if (
  result.amount === null ||
  !Number.isFinite(result.amount) ||
  result.amount <= 0
) {
  missing_fields.push('amount');
}

if (!result.transaction_date) {
  missing_fields.push('transaction_date');
}

if (!result.transaction_type) {
  missing_fields.push('transaction_type');
}

// We deliberately do NOT require merchant.
// Valid bank fees, transfers, ATM transactions, etc.
// may not contain a clean merchant.

// Require at least some account/card identity only later
// if business rules demand it.

result.missing_fields = missing_fields;

result.valid_transaction =
  missing_fields.length === 0;

// If normalization somehow failed, don't pretend parsing succeeded
result.parsed =
  result.valid_transaction;

// ------------------------------------------------------------
// 6. Return
// ------------------------------------------------------------

return {
  json: result
};

return [{
  json: $input.item.json
}];

const j = $json;

// Prefer merchant_raw, then merchant, then description
const rawMerchant = String(
  j.merchant_raw ??
  j.merchant ??
  j.description ??
  ''
).trim();

if (!rawMerchant) {
  return {
    json: {
      ...j,
      merchant_raw: null,
      merchant_normalized: null,
      merchant_display: null
    }
  };
}

let normalized = rawMerchant.toUpperCase();

// ------------------------------------------------------------
// 1. Remove common transaction-date/time suffixes
// Examples:
// AMAZON NOW ON 21 AUG, 2026 AT 21:05:51
// AMAZON NOW ON 21 AUG 2026 AT 21:05
// AMAZON NOW ON 21-08-2026 AT 21:05
// ------------------------------------------------------------

normalized = normalized.replace(
  /\s+ON\s+\d{1,2}\s+[A-Z]{3,12},?\s+\d{4}\s+AT\s+\d{1,2}:\d{2}(?::\d{2})?$/i,
  ''
);

normalized = normalized.replace(
  /\s+ON\s+\d{1,2}[-/]\d{1,2}[-/]\d{2,4}\s+AT\s+\d{1,2}:\d{2}(?::\d{2})?$/i,
  ''
);

// ------------------------------------------------------------
// 2. Remove common date-only suffixes
// ------------------------------------------------------------

normalized = normalized.replace(
  /\s+ON\s+\d{1,2}\s+[A-Z]{3,12},?\s+\d{4}$/i,
  ''
);

normalized = normalized.replace(
  /\s+ON\s+\d{1,2}[-/]\d{1,2}[-/]\d{2,4}$/i,
  ''
);

// ------------------------------------------------------------
// 3. Remove trailing time if it remains
// ------------------------------------------------------------

normalized = normalized.replace(
  /\s+AT\s+\d{1,2}:\d{2}(?::\d{2})?$/i,
  ''
);

// ------------------------------------------------------------
// 4. Normalize punctuation / whitespace
// ------------------------------------------------------------

normalized = normalized
  .replace(/[.,]+$/g, '')
  .replace(/\s+/g, ' ')
  .trim();

// ------------------------------------------------------------
// 5. Known merchant aliases / cleanup
// Keep this list small and deterministic.
// ------------------------------------------------------------

const merchantAliases = {
  'AMAZON NOW': 'AMAZON NOW',
  'AMAZONNOW': 'AMAZON NOW',
  'DECATHLON SPORTS INDIA': 'DECATHLON SPORTS',
  'DECATHLON SPORTS': 'DECATHLON SPORTS',
  'MICROSOFTBUSMUMBAIMAH': 'MICROSOFT',
  'GOOGLEWORKSPMUMBAIMAH': 'GOOGLE WORKSPACE',
  'GOOGLE WORKSP MUMBAI MAH': 'GOOGLE WORKSPACE'
};

if (merchantAliases[normalized]) {
  normalized = merchantAliases[normalized];
}

// ------------------------------------------------------------
// 6. Display name
// ------------------------------------------------------------

const displayOverrides = {
  'AMAZON NOW': 'Amazon Now',
  'DECATHLON SPORTS': 'Decathlon Sports India',
  'MICROSOFT': 'Microsoft',
  'GOOGLE WORKSPACE': 'Google Workspace'
};

const merchantDisplay =
  displayOverrides[normalized] ||
  normalized
    .toLowerCase()
    .replace(/\b\w/g, c => c.toUpperCase());

// ------------------------------------------------------------
// Return
// ------------------------------------------------------------

return {
  json: {
    ...j,

    merchant_raw: rawMerchant,

    merchant_normalized: normalized,

    merchant_display: merchantDisplay
  }
};

