const response = $json;

const text =
  response.candidates?.[0]?.content?.parts?.[0]?.text;

if (!text) {
  throw new Error('Gemini categorization returned no text');
}

let ai;

try {
  ai = JSON.parse(text);
} catch (e) {
  throw new Error(`Invalid Gemini JSON: ${text}`);
}

// Recover original transaction from the node BEFORE AI Categorize
const original = $('IF Merchant Known').item.json;

return {
  json: {
    ...original,

    display_name: ai.display_name || original.merchant_normalized || original.merchant_raw,
    merchant_normalized: ai.normalized_merchant || original.merchant_normalized,
    category: ai.category || 'Uncategorized',
    confidence: Number(ai.confidence ?? 0),

    category_source: 'ai'
  }
};

const j = $json;

if (j.amount == null) {
  throw new Error('Missing amount');
}

if (!j.transaction_date) {
  throw new Error('Missing transaction_date');
}

if (!j.category) {
  throw new Error('Missing category');
}

return {
  json: {
    user_id: '2f324f4d-1dc3-4ec5-8c23-93da480842c7',

    source_message_id: j.source_message_id || null,

    amount: Number(j.amount),
    currency: j.currency || 'INR',
    transaction_date: j.transaction_date,

    merchant:
      j.display_name ||
      j.merchant_normalized ||
      j.merchant_raw ||
      null,

    merchant_raw: j.merchant_raw || null,
    category: j.category,

    card_last4: j.card_last4 || null,
    account_last4: j.account_last4 || null,

    bank_name: j.bank || null,
    transaction_type: j.transaction_type || null,

    confidence:
  j.confidence != null
    ? (Number(j.confidence) > 1
        ? Number(j.confidence) / 100
        : Number(j.confidence))
    : null,

    category_source:
      j.category_source ||
      'merchant_memory',

    raw_email: j.raw_email || null,

    is_manually_entered: false,
    status: 'auto',

    processed_at: new Date().toISOString()
  }
};

// Get the original transaction before the HTTP Dedupe Check
const original = $('Prepare Dedupe').item.json;

// Get what Supabase Dedupe Check returned
const dedupeResult = $json;

// A real duplicate must contain an actual transaction identifier.
// An empty {} from "Always Output Data" is NOT a duplicate.
const isDuplicate = !!(
  dedupeResult &&
  (
    dedupeResult.id ||
    dedupeResult.source_message_id
  )
);

return {
  json: {
    ...original,

    is_duplicate: isDuplicate,

    duplicate_match: isDuplicate
      ? {
          id: dedupeResult.id ?? null,
          source_message_id: dedupeResult.source_message_id ?? null
        }
      : null
  }
};

const j = $json;

const required = [
  'user_id',
  'gmail_account_id',
  'message_id'
];

const missing = required.filter(
  key =>
    j[key] === undefined ||
    j[key] === null ||
    String(j[key]).trim() === ''
);

if (missing.length > 0) {
  throw new Error(
    `Missing required Workflow C input: ${missing.join(', ')}`
  );
}

return {
  json: {
    user_id: String(j.user_id).trim(),
    gmail_account_id: String(j.gmail_account_id).trim(),
    message_id: String(j.message_id).trim(),

    ingestion_source:
      j.ingestion_source || 'unknown',

    processing_started_at:
      new Date().toISOString()
  }
};

const gmail = $json;
const context = $("Validate Message Input").item.json;

return {
  json: {
    ...gmail,

    // Restore application/workflow context
    user_id: context.user_id,
    source_message_id: context.message_id || context.source_message_id || gmail.id,

    // Gmail identifiers
    message_id: gmail.id,
    thread_id: gmail.threadId || context.thread_id || null,

    // Keep RAW MIME
    raw: gmail.raw,

    // Optional routing context
    source: context.source || "gmail",
    source_account: context.source_account || null
  }
};

const j = $json;

// -------------------------------
// Required identity
// -------------------------------

const userId = j.user_id ?? null;
const sourceMessageId = j.source_message_id ?? null;

// -------------------------------
// Normalize transaction identity
// -------------------------------

const amount =
  j.amount !== null &&
  j.amount !== undefined &&
  Number.isFinite(Number(j.amount))
    ? Number(j.amount)
    : null;

const transactionDate =
  j.transaction_date
    ? String(j.transaction_date).slice(0, 10)
    : null;

const cardLast4 =
  j.card_last4
    ? String(j.card_last4).replace(/\D/g, '').slice(-4)
    : null;

const accountLast4 =
  j.account_last4
    ? String(j.account_last4).replace(/\D/g, '').slice(-4)
    : null;

const merchant =
  j.merchant_raw
    ? String(j.merchant_raw)
        .trim()
        .toUpperCase()
        .replace(/\s+/g, ' ')
    : null;

// -------------------------------
// Validation
// -------------------------------

if (!userId) {
  throw new Error('Cannot dedupe: user_id is missing');
}

if (!sourceMessageId) {
  throw new Error(
    'Cannot dedupe: source_message_id is missing'
  );
}

// -------------------------------
// Return FULL context
// -------------------------------

return {
  json: {
    ...j,

    dedupe: {
      user_id: userId,

      // Primary idempotency identifier
      source_message_id: sourceMessageId,

      // Secondary transaction fingerprint fields
      amount: amount,
      transaction_date: transactionDate,
      card_last4: cardLast4,
      account_last4: accountLast4,
      merchant_raw: merchant
    }
  }
};

const j = $json;

// --------------------------------------------------
// 1. SAFE HELPERS
// --------------------------------------------------

function hasValue(value) {
  return (
    value !== null &&
    value !== undefined &&
    String(value).trim() !== ''
  );
}

function validAmount(value) {
  const n = Number(value);
  return Number.isFinite(n) && n > 0;
}

function validDate(value) {
  if (!hasValue(value)) return false;

  const d = new Date(value);
  return !Number.isNaN(d.getTime());
}

// --------------------------------------------------
// 2. DETERMINE CRITICAL DATA QUALITY
// --------------------------------------------------

const missingFields = [];

if (!validAmount(j.amount)) {
  missingFields.push('amount');
}

if (!validDate(j.transaction_date)) {
  missingFields.push('transaction_date');
}

if (!hasValue(j.transaction_type)) {
  missingFields.push('transaction_type');
}

if (!hasValue(j.merchant) && !hasValue(j.merchant_raw)) {
  missingFields.push('merchant');
}

if (!hasValue(j.category)) {
  missingFields.push('category');
}

// --------------------------------------------------
// 3. NORMALIZE EXISTING CONFIDENCE
// --------------------------------------------------

let confidence = Number(j.confidence);

if (!Number.isFinite(confidence)) {
  confidence = 0;
}

// Support confidence accidentally expressed as 0–1
if (confidence > 0 && confidence <= 1) {
  confidence = confidence * 100;
}

confidence = Math.round(
  Math.max(0, Math.min(100, confidence))
);

// --------------------------------------------------
// 4. DETERMINE STATUS
// --------------------------------------------------

let status;

// Missing critical transaction data always requires review
if (missingFields.length > 0) {
  status = 'needs_review';
}

// High-confidence complete transaction
else if (confidence >= 90) {
  status = 'auto';
}

// Medium-confidence transaction
else if (confidence >= 70) {
  status = 'pending_review';
}

// Low-confidence transaction
else {
  status = 'needs_review';
}

// --------------------------------------------------
// 5. DETERMINE REVIEW REASON
// --------------------------------------------------

let reviewReason = null;

if (missingFields.length > 0) {
  reviewReason =
    `Missing/invalid fields: ${missingFields.join(', ')}`;
} else if (confidence < 70) {
  reviewReason = 'Low confidence';
} else if (confidence < 90) {
  reviewReason = 'Medium confidence';
}

// --------------------------------------------------
// 6. RETURN COMPLETE TRANSACTION
// --------------------------------------------------

return {
  json: {
    ...j,

    confidence,
    status,

    needs_review: status !== 'auto',

    review_reason: reviewReason,

    validation: {
      valid: missingFields.length === 0,
      missing_fields: missingFields
    }
  }
};

// ===========================================
// Build Context
// Version: v1
// Purpose:
// Convert raw Gmail output into platform context
// ===========================================

const j = $json;

// ---------- USER CONFIGURATION ----------
// Replace these only once for your installation
const USER_ID = "2f324f4d-1dc3-4ec5-8c23-93da480842c7";
const GMAIL_ACCOUNT_ID = "personal";

// ----------------------------------------

function getEmail(value) {
  if (!value) return '';

  if (typeof value === 'string') {
    const match = value.match(/<(.+?)>/);
    return match ? match[1].toLowerCase() : value.toLowerCase();
  }

  if (value.value?.length) {
    return (value.value[0].address || '').toLowerCase();
  }

  if (value.address) {
    return value.address.toLowerCase();
  }

  return '';
}

const sender = getEmail(j.from);
const recipient = getEmail(j.to);

return {
  json: {
    ...j,

    // ===================================
    // Platform Context
    // ===================================
    user_id: USER_ID,
    gmail_account_id: GMAIL_ACCOUNT_ID,
    ingestion_source: "gmail",

    // ===================================
    // Canonical Gmail identifiers
    // ===================================
    source_message_id: j.id,
    thread_id: j.threadId,

    // ===================================
    // Email identities
    // ===================================
    sender_email: sender,
    recipient_email: recipient,

    received_at: j.date ?? new Date().toISOString()
  }
};

// Lookup-only account resolution (no auto-creation -- `accounts` is the
// master registry, populated ahead of time). Matches on institution_name +
// last4. Credit cards additionally constrain account_type = 'Credit Card'
// (certain, from card_last4 alone). Savings/Current/OD do NOT constrain
// account_type here -- Workflow C's Bank Detection only distinguishes
// CREDIT_CARD_ALERT vs BANK_ACCOUNT_ALERT, never which of
// Savings/Current/OD a bank-account alert is. Per the explicit business
// assumption that last4 is unique within a bank's account registry, an
// account_last4 + institution_name match is expected to resolve to exactly
// one row regardless -- so account_type doesn't need to be (and can't be)
// specified on that side of the lookup.
const accounts = $input.all().map(i => i.json);
const txn = $('Build Final Transaction Row').first().json;

// "Bank Detection" short code -> accounts.institution_name. Confirmed
// against the live table for HDFC/ICICI/AXIS/SBI/AMEX. The rest are
// UNVERIFIED placeholders -- no matching account row exists yet to check
// against; correct these once the real accounts rows are added.
const BANK_NAME_MAP = {
  HDFC: 'HDFC Bank',
  ICICI: 'ICICI Bank',
  AXIS: 'Axis Bank',
  SBI: 'State Bank of India',
  AMEX: 'American Express',
  AU_BANK: 'AU Small Finance Bank',            // UNVERIFIED
  KOTAK: 'Kotak Mahindra Bank',                 // UNVERIFIED
  YES_BANK: 'YES Bank',                         // UNVERIFIED
  IDFC_FIRST: 'IDFC FIRST Bank',                // UNVERIFIED
  INDUSIND: 'IndusInd Bank',                    // UNVERIFIED
  STANDARD_CHARTERED: 'Standard Chartered Bank', // UNVERIFIED
  CITI: 'Citibank',                             // UNVERIFIED
  HSBC: 'HSBC',                                 // UNVERIFIED
};

function normAcct(s) { return (s == null ? '' : String(s)).trim().toLowerCase(); }

const canonicalBank = BANK_NAME_MAP[txn.bank_name] || txn.bank_name || null;

let account_match_status;
let candidates = [];

if (txn.card_last4) {
  candidates = accounts.filter(a =>
    normAcct(a.institution_name) === normAcct(canonicalBank) &&
    normAcct(a.account_type) === 'credit card' &&
    normAcct(a.card_last4) === normAcct(txn.card_last4)
  );
  account_match_status = candidates.length === 1 ? 'existing_account'
    : candidates.length > 1 ? 'ambiguous' : 'account_not_found';
} else if (txn.account_last4) {
  candidates = accounts.filter(a =>
    normAcct(a.institution_name) === normAcct(canonicalBank) &&
    normAcct(a.account_last4) === normAcct(txn.account_last4)
  );
  account_match_status = candidates.length === 1 ? 'existing_account'
    : candidates.length > 1 ? 'ambiguous' : 'account_not_found';
} else {
  account_match_status = 'insufficient_info';
}

const account_id = account_match_status === 'existing_account' ? candidates[0].id : null;

return [{
  json: {
    ...txn,
    account_id,
    account_match_status,
    canonical_bank_name: canonicalBank
  }
}];
